import { Group, Mesh, PlaneGeometry, Color, SRGBColorSpace, AdditiveBlending } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, fract, sin, dot, float, uniform, mul, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();

  const colors = config.intent?.visualSpec?.colors ?? {};
  const colorInk = new THREE.Color(colors.ink ?? '#16161d');
  const colorSurface = new THREE.Color(colors.surface ?? '#0b0b10');
  const colorAccent = new THREE.Color(colors.accent ?? '#ff2a38');
  const colorPaper = new THREE.Color(colors.paper ?? '#e8ecf2');

  // ── Backdrop: engineered gradient + subtle grain (never void) ──
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const uSurface = uniform(colorSurface);
  const uInk = uniform(colorInk);
  const vy = uv().y;
  const grad = mix(vec3(uSurface), vec3(uInk), smoothstep(float(0.0), float(1.0), vy));
  // radial darken toward edges for engineered depth
  const r = uv().sub(float(0.5));
  const radial = smoothstep(float(0.75), float(0.0), dot(r, r));
  const grad2 = grad.mul(radial.mul(float(0.5)).add(float(0.55)));
  // procedural grain
  const noise = fract(sin(dot(uv().mul(float(820.0)), vec2(12.9898, 78.233))).mul(float(43758.5453)));
  backdropMat.colorNode = grad2.add(vec3(noise.mul(float(0.022))));
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // ── Accent halo behind sprite (depth + one-brightest anchor) ──
  const haloGeo = new PlaneGeometry(3.4, 2.2);
  const haloMat = new MeshBasicNodeMaterial({ transparent: true, blending: AdditiveBlending, depthWrite: false });
  const hc = uv().sub(float(0.5));
  const hd = dot(hc, hc);
  const haloFalloff = smoothstep(float(0.28), float(0.0), hd);
  haloMat.colorNode = vec3(colorAccent).mul(haloFalloff.mul(float(0.16)));
  haloMat.opacity = 0;
  const halo = new Mesh(haloGeo, haloMat);
  halo.position.set(0, -0.35, -1.1);
  group.add(halo);

  // ── Hero sprite (billboarded toward +Z camera) ──
  const aspect = 512 / 320; // 1.6
  const planeW = 2.6;
  const planeH = planeW / aspect;
  const spriteGeo = new PlaneGeometry(planeW, planeH);
  const spriteMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  spriteMat.opacity = 0;
  const sprite = new Mesh(spriteGeo, spriteMat);
  sprite.position.set(0, -0.35, -0.6);
  group.add(sprite);

  // Load accent texture (atlas region 0,0,512,320 == full image)
  const imgUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  let spriteTexture = null;
  if (imgUrl && ctx.textureLoader) {
    ctx.textureLoader.loadTexture(imgUrl).then((tex) => {
      spriteTexture = tex;
      tex.colorSpace = SRGBColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      spriteMat.map = tex;
      spriteMat.transparent = true;
      spriteMat.needsUpdate = true;
    });
  }

  // ── Contact shadow grounding the sprite ──
  const shadowGeo = new PlaneGeometry(3.2, 1.1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const sc = uv().sub(float(0.5));
  const sd = dot(sc, sc);
  const shadowFalloff = smoothstep(float(0.25), float(0.0), sd);
  shadowMat.colorNode = vec3(float(0.0)).mul(shadowFalloff);
  shadowMat.opacityNode = shadowFalloff.mul(float(0.5));
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -1.55, -0.65);
  shadow.rotation.x = -0.18;
  group.add(shadow);

  // ── Foreground accent spark (depth plane 3) ──
  const sparkGeo = new PlaneGeometry(0.12, 0.12);
  const sparkMat = new MeshBasicNodeMaterial({ transparent: true, blending: AdditiveBlending, depthWrite: false });
  const ssc = uv().sub(float(0.5));
  const sparkFalloff = smoothstep(float(0.5), float(0.0), dot(ssc, ssc));
  sparkMat.colorNode = vec3(colorPaper).mul(sparkFalloff);
  sparkMat.opacity = 0;
  const spark = new Mesh(sparkGeo, sparkMat);
  spark.position.set(1.7, 0.4, 0.4);
  group.add(spark);

  // ── Entrance: rise-in + weighted-settle ──
  sprite.position.y = -0.35 + 0.4;
  sprite.scale.setScalar(1.04);
  const tl = gsap.timeline();
  tl.to(sprite.position, { y: -0.35, duration: 0.7, ease: 'power3.out' }, 0)
    .to(sprite.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0)
    .to(spriteMat, { opacity: 1.0, duration: 0.6, ease: 'power2.out' }, 0)
    .to(haloMat, { opacity: 1.0, duration: 0.9, ease: 'power2.out' }, 0.15)
    .to(sparkMat, { opacity: 0.8, duration: 0.5, ease: 'power2.out' }, 0.4)
    .to(spark.position, { y: 0.55, duration: 1.2, ease: 'sine.inOut', yoyo: true, repeat: 1 }, 0.4);

  // ── Subtle idle breathing on the halo (one slow transform) ──
  const idle = gsap.to(halo.scale, {
    x: 1.06, y: 1.06, z: 1.0,
    duration: 3.2, ease: 'sine.inOut',
    yoyo: true, repeat: -1
  });

  // ── Event handlers surface (none wired per spec) ──
  group.userData.handlers = {};

  // ── Cleanup ──
  group.userData.cleanup = () => {
    tl.kill();
    idle.kill();
    backdropGeo.dispose();
    backdropMat.dispose();
    haloGeo.dispose();
    haloMat.dispose();
    spriteGeo.dispose();
    spriteMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    sparkGeo.dispose();
    sparkMat.dispose();
    if (spriteTexture) spriteTexture.dispose();
  };

  return group;
}
